-- ----------------------------------------------------------------------------
-- 2. Verify block — mirrors the pattern from migrations 040-044.
--    Re-asserts the canonical prereq baseline (ADR 0004) so this migration
--    cannot silently drift it, then validates the content invariants:
--      - the target skill row exists and was updated;
--      - common_misconceptions contains exactly 4 entries;
--      - every expected ID is present (set equality, not subset);
--      - every entry carries the canonical six keys
--        (id, label, description, contradicts_principle, distinguishing_mcq_stem, label_ar);
--      - every distinguishing_mcq_stem carries the five structured sub-keys
--        (stem_text, distractor_choice_label, distractor_rationale, correct_choice_label, correct_rationale).
-- ----------------------------------------------------------------------------
DO $verify$
DECLARE
  v_mc_count        INT;
  v_actual_ids      TEXT[];
  v_offender_id     TEXT;
  v_skill_id        UUID;
  -- prereq baseline (must be unchanged by this migration)
  v_total           INT;
  v_sma             INT;
  v_smb             INT;
  v_pc              INT;
  v_svt             INT;
  v_humanities      INT;
  v_cross           INT;
  v_expected_ids    TEXT[] := ARRAY[
    'mc.math.sma_limit_calc.forme-indeterminee-valeur-nulle',
    'mc.math.sma_limit_calc.limite-egale-valeur-point',
    'mc.math.sma_limit_calc.infini-moins-infini-nul',
    'mc.math.sma_limit_calc.limite-fondamentale-linearite'
  ];
BEGIN
  -- 2a. The target skill row exists.
  SELECT id INTO v_skill_id FROM public.skills WHERE code = 'sma_limit_calc';
  IF v_skill_id IS NULL THEN
    RAISE EXCEPTION 'Migration 045 post-condition failed: skill `sma_limit_calc` not found.';
  END IF;

  -- 2b. common_misconceptions has exactly the expected entry count.
  SELECT jsonb_array_length(common_misconceptions)
  INTO   v_mc_count
  FROM   public.skills
  WHERE  code = 'sma_limit_calc';
  IF v_mc_count IS DISTINCT FROM 4 THEN
    RAISE EXCEPTION 'Migration 045 post-condition failed: expected 4 misconceptions on `sma_limit_calc`, got %.', v_mc_count;
  END IF;

  -- 2c. Set equality on misconception IDs (no missing, no extra).
  SELECT array_agg(elem->>'id' ORDER BY elem->>'id')
  INTO   v_actual_ids
  FROM   public.skills,
         LATERAL jsonb_array_elements(common_misconceptions) AS elem
  WHERE  code = 'sma_limit_calc';

  IF NOT (v_actual_ids @> v_expected_ids AND v_expected_ids @> v_actual_ids) THEN
    RAISE EXCEPTION 'Migration 045 post-condition failed: misconception ID set mismatch. expected=%, actual=%', v_expected_ids, v_actual_ids;
  END IF;

  -- 2d. Every entry carries the canonical six keys.
  SELECT elem->>'id'  INTO   v_offender_id
  FROM   public.skills,
         LATERAL jsonb_array_elements(common_misconceptions) AS elem
  WHERE  code = 'sma_limit_calc'    AND  NOT (
           elem ? 'id' AND
           elem ? 'label' AND
           elem ? 'description' AND
           elem ? 'contradicts_principle' AND
           elem ? 'distinguishing_mcq_stem' AND
           elem ? 'label_ar'         )
  LIMIT 1;
  IF v_offender_id IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 045 post-condition failed: misconception "%" is missing one of the six canonical keys.', v_offender_id;
  END IF;

  -- 2e. Every distinguishing_mcq_stem is an object with the five structured sub-keys
  --     (per ADR 0009 §B.2 — step 3 reads distractor_choice_label and correct_choice_label).
  SELECT elem->>'id'  INTO   v_offender_id
  FROM   public.skills,
         LATERAL jsonb_array_elements(common_misconceptions) AS elem
  WHERE  code = 'sma_limit_calc'    AND  NOT (
           jsonb_typeof(elem -> 'distinguishing_mcq_stem') = 'object' AND
           (elem -> 'distinguishing_mcq_stem') ? 'stem_text' AND
           (elem -> 'distinguishing_mcq_stem') ? 'distractor_choice_label' AND
           (elem -> 'distinguishing_mcq_stem') ? 'distractor_rationale' AND
           (elem -> 'distinguishing_mcq_stem') ? 'correct_choice_label' AND
           (elem -> 'distinguishing_mcq_stem') ? 'correct_rationale'         )
  LIMIT 1;
  IF v_offender_id IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 045 post-condition failed: misconception "%" distinguishing_mcq_stem missing structured sub-keys.', v_offender_id;
  END IF;

  -- 2f. Prereq baseline — must be unchanged. Re-asserts ADR 0004's canonical
  --     counts so this content migration cannot silently drift them.
  WITH skill_stream AS (
    SELECT
      sk.id,
      CASE
        WHEN sk.code LIKE 'sma\_%' ESCAPE '\' THEN 'SMA'
        WHEN sk.code LIKE 'pc\_%'  ESCAPE '\' THEN 'PC'
        WHEN sk.code LIKE 'svt\_%' ESCAPE '\' THEN 'SVT'
        WHEN sub.code IN ('math','physics','svt') THEN 'SMB'
        ELSE                                           'humanities'
      END AS stream
    FROM public.skills    sk
    JOIN public.topics    t   ON t.id   = sk.topic_id
    JOIN public.subjects  sub ON sub.id = t.subject_id
  )
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE dep.stream = 'SMA'),
    COUNT(*) FILTER (WHERE dep.stream = 'SMB'),
    COUNT(*) FILTER (WHERE dep.stream = 'PC'),
    COUNT(*) FILTER (WHERE dep.stream = 'SVT'),
    COUNT(*) FILTER (WHERE dep.stream = 'humanities'),
    COUNT(*) FILTER (WHERE dep.stream <> pre.stream)
  INTO  v_total, v_sma, v_smb, v_pc, v_svt, v_humanities, v_cross
  FROM  public.skill_prerequisites sp
  JOIN  skill_stream dep ON dep.id = sp.skill_id
  JOIN  skill_stream pre ON pre.id = sp.prerequisite_skill_id;

  IF v_sma        <> 98  THEN RAISE EXCEPTION 'Migration 045 prereq baseline: SMA expected 98, got %', v_sma; END IF;
  IF v_smb        <> 31  THEN RAISE EXCEPTION 'Migration 045 prereq baseline: SMB expected 31, got %', v_smb; END IF;
  IF v_pc         <> 21  THEN RAISE EXCEPTION 'Migration 045 prereq baseline: PC expected 21, got %', v_pc; END IF;
  IF v_svt        <> 9   THEN RAISE EXCEPTION 'Migration 045 prereq baseline: SVT expected 9, got %', v_svt; END IF;
  IF v_humanities <> 42  THEN RAISE EXCEPTION 'Migration 045 prereq baseline: humanities expected 42, got %', v_humanities; END IF;
  IF v_total      <> 201 THEN RAISE EXCEPTION 'Migration 045 prereq baseline: total expected 201, got %', v_total; END IF;
  IF v_cross      <> 0   THEN RAISE EXCEPTION 'Migration 045 prereq baseline: cross-stream edges expected 0, got %', v_cross; END IF;

  RAISE NOTICE
    'Migration 045 verification OK: skill=`sma_limit_calc` misconceptions=% expected_ids_match=true six_keys_present=true structured_stem_shape=true prereq_baseline=unchanged (total=% SMA=% SMB=% PC=% SVT=% humanities=% cross=%)',
    v_mc_count, v_total, v_sma, v_smb, v_pc, v_svt, v_humanities, v_cross;
END
$verify$;

COMMIT;

